// Ten values average and above average using this
import java.util.Scanner;public class Q11 {private final double[] values=new double[10];void read(Scanner input){for(int i=0;i<this.values.length;i++){System.out.print("Enter number "+(i+1)+": ");this.values[i]=input.nextDouble();}}void report(){double sum=0;for(double n:this.values)sum+=n;double average=sum/this.values.length;int count=0;for(double n:this.values)if(n>average)count++;System.out.printf("Average: %.2f, Above average: %d%n",average,count);}public static void main(String[] args){Q11 result=new Q11();try(Scanner sc=new Scanner(System.in)){result.read(sc);result.report();}}}
